    DrawerApi.prototype._checkObject = function(obj) {
        if (!obj) {
            throw new Error('[Drawer API]  no object provided!');
        }
        if (!(obj instanceof fabric.Object)) {
            throw new Error("[Drawer API]  object type is not 'fabric.Object!'");
        }
    };


