        offsetLeft = sizes.centerX - sizes.paletteSizes.width/2;
        offsetTop = sizes.canvasSizes.height - sizes.bottom + sizes.palette.arrowSize;
        styles.top = sizes.top - popupOffsetTop + sizes.triggerSizes.height;
